// === Tab: main ===
var particles = [];
var colors = [[]];
var colorsIndex = 0;
var sides = 8;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);

	colors[0] = [
		color(211, 84, 0),
		color(231, 76, 60),
		color(241, 196, 15),
		color(230, 126, 34)
	];

	colors[1] = [
		color(84, 153, 199),
		color(93, 173, 226),
		color(52, 152, 219),
		color(88, 214, 141)
	];

	colors[2] = [
		color(142, 68, 173),
		color(165, 105, 189),
		color(251, 252, 252),
		color(215, 219, 221)
	];

	for (let i = 0; i < 50; i++)
		particles.push(new Particle());

	fill(0);
	strokeWeight(7);
	// frameRate(40);
}

function draw() {
	background(0, 10);

	particles.forEach(particle => particle.update());

	push();
	translate(width / 2, height / 2);
	for (let i = 0; i < sides; i++) {
		particles.forEach(particle => particle.draw());
		rotate(TAU / sides);
	}
	pop();

	noStroke();
	fill(25);
	beginShape();
	vertex(width, height);
	vertex(width, 0     );
	vertex(0    , 0     );
	vertex(0    , height);
	vertex(width, height);
	for (let i = 0; i < sides; i++)
		vertex(320 * cos(i * TAU / sides) + width / 2, 320 * sin(i * TAU / sides) + height / 2);
	vertex(320 + width / 2, height / 2);
	endShape(CLOSE);
}

Particle = function() {
	this.position = createVector(random(640), random(640));
	this.velocity = createVector(random(-1, 1), random(-1, 1));
	this.velocity.setMag(2);
	this.index = floor(random(colors[colorsIndex].length));

	this.draw = function() {
		stroke(colors[colorsIndex][this.index]);
		point(this.position.x - 320, this.position.y - 320);
	}

	this.update = function() {
		this.position.add(this.velocity);

		if (this.position.x < 0 || this.position.x > 640) this.velocity.x *= -1;
		if (this.position.y < 0 || this.position.y > 640) this.velocity.y *= -1;
	}
}

function mouseMoved() {
	sides = constrain(map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 2, 12), 4, 10);
}

function mousePressed() {
	colorsIndex ++;
	if (colorsIndex >= colors.length)
		colorsIndex = 0;
}

